// План specs/leads-map.md 1.1–1.2 (кейсы LM-01, LM-02). Admin, компания «test». Только просмотр /map.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from '../addresses/address-helpers';
import { QA_MAP_LEAD, TEST_LEAD, cardLines, leadCard, openLeadsMap } from './map-helpers';

test.use({ storageState: ADMIN_STATE });

// Сценарий тикета — мобильный (Android/Chrome) + проверка десктопа: по тесту на устройство.
for (const device of ['@desktop', '@android'] as const) {
  test.describe(`Leads Map: карточка лида без лишнего «0» (#dc2f0de9) ${device}`, () => {
    test(`Map: lead "test" card shows the address under the phone and no "0" line #dc2f0de9 ${device} @prod-safe`, async ({ page }) => {
      await setEnglish(page);
      await openLeadsMap(page);

      const lines = await cardLines(leadCard(page, TEST_LEAD.name, TEST_LEAD.phone), TEST_LEAD.address);
      // «מה רצוי»: нет «0» (это был Estimated Value = 0).
      expect(lines, 'строка «0» в карточке «test»').not.toContain('0');
      // «מה רצוי»: есть адрес — он показан сразу под телефоном.
      const phoneAt = lines.indexOf(TEST_LEAD.phone);
      expect(phoneAt, 'телефон в карточке').toBeGreaterThanOrEqual(0);
      expect(lines[phoneAt + 1], 'строка под телефоном').toBe(TEST_LEAD.address);
    });

    test(`Map: lead without an address ("QA-map lead") shows "No coordinates" and no "0" #dc2f0de9 ${device} @prod-safe`, async ({ page }) => {
      await setEnglish(page);
      await openLeadsMap(page);

      const lines = await cardLines(leadCard(page, QA_MAP_LEAD.name, QA_MAP_LEAD.phone), 'No coordinates');
      // «מה רצוי»: нет адреса — ничего вместо него (без «0»).
      expect(lines, 'строка «0» в карточке без адреса').not.toContain('0');
      expect(lines.filter((l) => /^\$?0(\.00)?$/.test(l)), 'нулевое значение в карточке').toEqual([]);
    });
  });
}
